from functools import lru_cache as _lru


def _ref_ed(a, b):
    @_lru(maxsize=None)
    def _go(i, j):
        if i == 0:
            return j
        if j == 0:
            return i
        if a[i - 1] == b[j - 1]:
            return _go(i - 1, j - 1)
        return 1 + min(_go(i - 1, j - 1), _go(i - 1, j), _go(i, j - 1))
    return _go(len(a), len(b))


